def consolidate_roles(apps, schema_editor):
    """MANAGER and SUPER_ADMIN become ADMIN. One audit record per person keeps the role they had."""
    Staff = apps.get_model("ops", "Staff")
    AuditEvent = apps.get_model("core", "AuditEvent")
    for staff in Staff.objects.filter(role__in=RETIRED).order_by("id"):
        AuditEvent.objects.create(action="staff.role_consolidated", actor_id=None, actor_label="migration",
                                  channel="system", entity_type="staff", entity_id=staff.id,
                                  summary={"before": staff.role, "after": "ADMIN", "adr": "0011"})
        Staff.objects.filter(pk=staff.pk).update(role="ADMIN")


def restore_roles(apps, schema_editor):
    """Rollback: give each consolidated person the role recorded in their audit record."""
    Staff = apps.get_model("ops", "Staff")
    AuditEvent = apps.get_model("core", "AuditEvent")
    for event in AuditEvent.objects.filter(action="staff.role_consolidated", entity_type="staff").order_by("id"):
        before = (event.summary or {}).get("before")
        if before in RETIRED:
            Staff.objects.filter(pk=event.entity_id, role="ADMIN").update(role=before)


